// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(address caller, uint256 val) public {
        vm.assume(caller != address(0));

        bool firstOk;
        vm.prank(caller);
        try c.SetMinSum(val) {
            firstOk = true;
        } catch {
            firstOk = false;
        }

        bool secondOk;
        vm.prank(caller);
        try c.SetMinSum(val) {
            secondOk = true;
        } catch {
            secondOk = false;
        }

        assertTrue(!firstOk || secondOk);
    }
}
